  function openCardPurchase(cardId){const c=S.v5.cards.find(x=>x.id===cardId);if(!c)return;md.cardId=cardId;M(`<h2>Compra · ${escA(c.name)}</h2>${mInput('Descrição','v51','')}${mInput('Valor total (R$)','v52','','text','inputmode="decimal"')}${mInput('Data da compra','v53',TD,'date')}${mInput('Parcelas','v54',1,'number','min="1" max="60"')}${selectInput('Escopo','v55',[['casa','Casa'],['obra','Obra']],'casa')}<label>Categoria</label><select id="v56">${ALL.map(c=>`<option>${escA(c)}</option>`).join('')}</select><label>Fornecedor</label><select id="v57"><option value="">Não informado</option>${S.v5.suppliers.map(s=>`<option value="${s.id}">${escA(s.name)}</option>`).join('')}</select><div id="er" class="out"></div><button class="pri" onclick="saveCardPurchase()">Salvar compra</button>${btns()}`)}window.openCardPurchase=openCardPurchase;
  function saveCardPurchase(){const c=S.v5.cards.find(x=>x.id===md.cardId),desc=$('#v51').value.trim(),total=pv($('#v52').value),date=$('#v53').value,parts=parseInt($('#v54').value)||1;if(!c||!desc||!(total>0)||parts<1)return $('#er').textContent='Confira descrição, valor e parcelas.';const base=Math.floor(total*100/parts)/100,last=Math.round((total-base*(parts-1))*100)/100;for(let i=0;i<parts;i++){const d=new Date(date+'T12:00:00');d.setMonth(d.getMonth()+i);const dt=ymd(d),invoiceMonth=invoiceMonthFor(c,dt);v5Add('cardCharges',{cardId:c.id,purchaseId:uid(),desc,amount:i===parts-1?last:base,purchaseDate:date,installment:i+1,installments:parts,invoiceMonth,dueDate:invoiceDueDate(c,invoiceMonth),scope:$('#v55').value,cat:$('#v56').value,supplierId:$('#v57').value,paid:false})}audit('Compra parcelada cadastrada',`${desc} · ${parts}x · ${brl(total)}`,'card');save();closeM();render()}window.saveCardPurchase=saveCardPurchase;
  function openInvoice(cardId,m){const c=S.v5.cards.find(x=>x.id===cardId),L=S.v5.cardCharges.filter(x=>x.cardId===cardId&&x.invoiceMonth===m&&!x.paid),tot=sum(L);M(`<h2>Fatura ${escA(c?.name||'')}</h2><div class="big2 out">${brl(tot)}</div><div class="mu">${m} · vence ${fmtDate(invoiceDueDate(c,m))}</div><div class="card" style="margin-top:10px">${L.map(x=>`<div class="it"><div class="t"><b>${escA(x.desc)}</b><span class="mu">${x.installment}/${x.installments}</span></div><b>${brl(x.amount)}</b></div>`).join('')}</div><label>Debitar pagamento de</label>${walletSelect('v5wallet')}<div id="er" class="out"></div><button class="pri" onclick="payInvoice('${cardId}','${m}')">Pagar fatura</button>${btns()}`)}window.openInvoice=openInvoice;
  function payInvoice(cardId,m){const L=S.v5.cardCharges.filter(x=>x.cardId===cardId&&x.invoiceMonth===m&&!x.paid),tot=sum(L),w=$('#v5wallet').value;if(!L.length)return toast('Fatura já está paga.');if(!walletApply(w,-tot,'Pagamento de fatura '+m))return;L.forEach(x=>v5Stamp(Object.assign(x,{paid:true,paidAt:isoNow(),walletKey:w})));audit('Fatura paga',`${m} · ${brl(tot)} · ${walletLabel(w)}`,'card');save();closeM();render()}window.payInvoice=payInvoice;

  // Fornecedores e PIX.
  function supplierSpend(s){return sum(S.tx.filter(x=>x.type==='out'&&String(x.sup||'').toLowerCase()===String(s.name||'').toLowerCase()))}
  function renderSuppliers(){const q=(window.v5SupplierQuery||'').toLowerCase(),L=S.v5.suppliers.filter(s=>!q||s.name.toLowerCase().includes(q));return page('Fornecedores','Contatos, Pix e histórico de compras',`<div class="card"><input class="v5search" placeholder="Buscar fornecedor" value="${escA(window.v5SupplierQuery||'')}" oninput="window.v5SupplierQuery=this.value;render()"></div>${L.map(s=>`<div class="card"><div class="row sp"><div><b>${escA(s.name)}</b><div class="mu">${escA(s.taxId||'')}${s.phone?' · '+escA(s.phone):''}</div></div><button class="ghost" onclick="openSupplier('${s.id}')">Editar</button></div><div class="row sp" style="margin-top:8px"><span class="mu">Compras registradas</span><b>${brl(supplierSpend(s))}</b></div>${s.pix?`<div class="v5pix"><span>⚡ ${escA(s.pix)}</span><button class="ghost" onclick="doCopy('${escA(s.pix)}')">Copiar Pix</button></div>`:''}</div>`).join('')||empty('Nenhum fornecedor cadastrado.')}`,`<button class="pri" style="margin:0 0 12px" onclick="openSupplier()">+ Novo fornecedor</button>`)}
  function openSupplier(id){const x=S.v5.suppliers.find(v=>v.id===id);md.v5id=id||null;M(`<h2>${x?'Editar fornecedor':'Novo fornecedor'}</h2>${mInput('Nome','v51',x?.name||'')}${mInput('CPF/CNPJ','v52',x?.taxId||'')}${mInput('Telefone','v53',x?.phone||'')}${mInput('Chave Pix','v54',x?.pix||'')}${mInput('Banco','v55',x?.bank||'')}${textArea('Observações','v56',x?.note||'')}<button class="pri" onclick="saveSupplier()">Salvar</button>${x?`<button class="ghost out v5full" onclick="v5Delete('suppliers','${x.id}')">Excluir</button>`:''}${btns()}`)}window.openSupplier=openSupplier;
  function saveSupplier(){const name=$('#v51').value.trim();if(!name)return toast('Informe o nome.');const p={name,taxId:$('#v52').value.trim(),phone:$('#v53').value.trim(),pix:$('#v54').value.trim(),bank:$('#v55').value.trim(),note:$('#v56').value.trim()};if(md.v5id)v5Update('suppliers',md.v5id,p);else v5Add('suppliers',p);audit('Fornecedor salvo',name,'supplier');save();closeM();render()}window.saveSupplier=saveSupplier;

  // Metas.
  function renderGoals(){return page('Metas financeiras','Reservas e objetivos',S.v5.goals.map(g=>{const p=pct(g.current,g.target);return `<div class="card"><div class="row sp"><div><b>${escA(g.name)}</b><div class="mu">${g.due?`Meta até ${fmtDate(g.due)}`:'Sem prazo'}</div></div>${chip(g.done?'Concluída':p+'%',g.done?'ok':'')}</div><div class="bar"><i style="width:${clamp(p,0,100)}%"></i></div><div class="row sp"><span>${brl(g.current)} de ${brl(g.target)}</span><button class="ghost" onclick="openGoal('${g.id}')">Atualizar</button></div></div>`}).join('')||empty('Cadastre uma meta financeira.'),`<button class="pri" style="margin:0 0 12px" onclick="openGoal()">+ Nova meta</button>`)}
  function openGoal(id){const x=S.v5.goals.find(v=>v.id===id);md.v5id=id||null;M(`<h2>${x?'Atualizar meta':'Nova meta'}</h2>${mInput('Nome','v51',x?.name||'')}${mInput('Objetivo (R$)','v52',x?String(x.target).replace('.',','):'','text','inputmode="decimal"')}${mInput('Já reservado (R$)','v53',x?String(x.current).replace('.',','):'0','text','inputmode="decimal"')}${mInput('Prazo','v54',x?.due||'','date')}<button class="pri" onclick="saveGoal()">Salvar</button>${x?`<button class="ghost out v5full" onclick="v5Delete('goals','${x.id}')">Excluir</button>`:''}${btns()}`)}window.openGoal=openGoal;
  function saveGoal(){const name=$('#v51').value.trim(),target=pv($('#v52').value),current=pv($('#v53').value||'0');if(!name||!(target>0)||isNaN(current))return toast('Confira os valores.');const p={name,target,current,due:$('#v54').value,done:current>=target};if(md.v5id)v5Update('goals',md.v5id,p);else v5Add('goals',p);audit('Meta salva',name,'goal');save();closeM();render()}window.saveGoal=saveGoal;

  // Lista de compras.
  function renderShopping(){const L=S.v5.shopping.filter(x=>!x.done),done=S.v5.shopping.filter(x=>x.done);return page('Lista de compras','Planeje antes de virar despesa',`<div class="card"><h2>Pendentes</h2>${L.map(x=>`<div class="it"><div class="ic">${x.scope==='obra'?'🏗️':'🛒'}</div><div class="t"><b>${escA(x.item)}</b><span class="mu">${escA(x.qty||'')} ${escA(x.unit||'')} · ${escA(x.cat||'Outros')}${x.estimate?` · est. ${brl(x.estimate)}`:''}</span></div><button class="ghost" onclick="convertShopping('${x.id}')">Comprar</button><button class="x" onclick="toggleShopping('${x.id}')">✓</button></div>`).join('')||empty('Nada pendente.')}</div><div class="card"><h2>Concluídos</h2>${done.slice(0,20).map(x=>`<div class="it pd"><div class="t"><b>${escA(x.item)}</b></div><button class="x" onclick="toggleShopping('${x.id}')">↩</button></div>`).join('')||empty('Nenhum item concluído.')}</div>`,`<button class="pri" style="margin:0 0 12px" onclick="openShopping()">+ Novo item</button>`)}
  function openShopping(){M(`<h2>Novo item</h2>${mInput('Item','v51','')}${mInput('Quantidade','v52','')}${mInput('Unidade','v53','un')}${selectInput('Escopo','v54',[['obra','Obra'],['casa','Casa']],'obra')}<label>Categoria</label><select id="v55">${ALL.map(c=>`<option>${escA(c)}</option>`).join('')}</select>${mInput('Valor estimado (R$)','v56','','text','inputmode="decimal"')}<button class="pri" onclick="saveShopping()">Adicionar</button>${btns()}`)}window.openShopping=openShopping;
  function saveShopping(){const item=$('#v51').value.trim(),estimate=pv($('#v56').value||'0');if(!item||isNaN(estimate))return toast('Confira o item.');v5Add('shopping',{item,qty:$('#v52').value.trim(),unit:$('#v53').value.trim(),scope:$('#v54').value,cat:$('#v55').value,estimate,done:false});audit('Item adicionado à lista',item,'shopping');save();closeM();render()}window.saveShopping=saveShopping;
  function toggleShopping(id){const x=S.v5.shopping.find(v=>v.id===id);if(!x)return;x.done=!x.done;v5Stamp(x);save();render()}window.toggleShopping=toggleShopping;
  function convertShopping(id){const x=S.v5.shopping.find(v=>v.id===id);if(!x)return;md.v5shopping=id;M(`<h2>Transformar em despesa</h2><div class="mu">${escA(x.item)}</div>${mInput('Valor final (R$)','v51',String(x.estimate||'').replace('.',','),'text','inputmode="decimal"')}${mInput('Data','v52',TD,'date')}<label>Debitar de</label>${walletSelect('v5wallet')}<label>Fornecedor</label><select id="v53"><option value="">Não informado</option>${S.v5.suppliers.map(s=>`<option value="${s.id}">${escA(s.name)}</option>`).join('')}</select><button class="pri" onclick="saveShoppingExpense()">Criar despesa</button>${btns()}`)}window.convertShopping=convertShopping;
  function saveShoppingExpense(){const x=S.v5.shopping.find(v=>v.id===md.v5shopping),val=pv($('#v51').value),date=$('#v52').value,walletKey=$('#v5wallet').value,sup=S.v5.suppliers.find(s=>s.id===$('#v53').value)?.name||'';if(!x||!(val>0))return toast('Informe o valor.');const t=stamp({id:uid(),scope:x.scope,type:'out',desc:x.item,val,cat:x.cat||'Outros',sup,date,walletKey,pay:'',pixKey:'',_u:now()});S.tx.push(t);x.done=true;v5Stamp(x);audit('Compra convertida em despesa',`${x.item} · ${brl(val)}`,'shopping',x.id);save();notifyActivity('financial',t);closeM();render()}window.saveShoppingExpense=saveShoppingExpense;

  // Cotações.
  function renderQuotes(){const order={cotacao:0,aprovado:1,comprado:2,pago:3};return page('Cotações','Da pesquisa até o pagamento',S.v5.quotes.slice().sort((a,b)=>order[a.status]-order[b.status]).map(q=>`<div class="card"><div class="row sp"><div><b>${escA(q.desc)}</b><div class="mu">${escA(q.supplier||'Sem fornecedor')} · ${brl(q.amount)}</div></div>${chip({cotacao:'Cotação',aprovado:'Aprovado',comprado:'Comprado',pago:'Pago'}[q.status]||q.status)}</div><div class="row" style="margin-top:10px"><button class="ghost" style="flex:1" onclick="advanceQuote('${q.id}')">Avançar etapa</button><button class="ghost" onclick="openQuote('${q.id}')">Editar</button></div></div>`).join('')||empty('Nenhuma cotação cadastrada.'),`<button class="pri" style="margin:0 0 12px" onclick="openQuote()">+ Nova cotação</button>`)}
  function openQuote(id){const x=S.v5.quotes.find(v=>v.id===id);md.v5id=id||null;M(`<h2>${x?'Editar cotação':'Nova cotação'}</h2>${mInput('Descrição','v51',x?.desc||'')}${mInput('Fornecedor','v52',x?.supplier||'')}${mInput('Valor (R$)','v53',x?String(x.amount).replace('.',','):'','text','inputmode="decimal"')}${selectInput('Escopo','v54',[['obra','Obra'],['casa','Casa']],x?.scope||'obra')}<label>Categoria</label><select id="v55">${ALL.map(c=>`<option${x?.cat===c?' selected':''}>${escA(c)}</option>`).join('')}</select>${selectInput('Status','v56',[['cotacao','Cotação'],['aprovado','Aprovado'],['comprado','Comprado'],['pago','Pago']],x?.status||'cotacao')}${textArea('Observações','v57',x?.note||'')}<button class="pri" onclick="saveQuote()">Salvar</button>${x?`<button class="ghost out v5full" onclick="v5Delete('quotes','${x.id}')">Excluir</button>`:''}${btns()}`)}window.openQuote=openQuote;
  function saveQuote(){const desc=$('#v51').value.trim(),amount=pv($('#v53').value);if(!desc||!(amount>=0))return toast('Confira a cotação.');const p={desc,supplier:$('#v52').value.trim(),amount,scope:$('#v54').value,cat:$('#v55').value,status:$('#v56').value,note:$('#v57').value.trim()};if(md.v5id)v5Update('quotes',md.v5id,p);else v5Add('quotes',p);audit('Cotação salva',desc,'quote');save();closeM();render()}window.saveQuote=saveQuote;
  function advanceQuote(id){const x=S.v5.quotes.find(v=>v.id===id);if(!x)return;const seq=['cotacao','aprovado','comprado','pago'];x.status=seq[Math.min(seq.length-1,seq.indexOf(x.status)+1)];v5Stamp(x);audit('Cotação avançou de etapa',`${x.desc} → ${x.status}`,'quote',x.id);save();render()}window.advanceQuote=advanceQuote;

  // Transferência universal e conciliação.
  function renderWalletStatement(){const logs=[...S.alog.map(x=>({...x,src:'Conta'})),...S.cashlog.map(x=>({...x,a:'Dinheiro em mãos',src:'Dinheiro'})),...S.vlog.map(x=>({...x,src:'VR'}))].sort((a,b)=>n(b._u)-n(a._u)).slice(0,80);return `<div class="card"><div class="row sp"><h2>Extrato consolidado</h2><button class="ghost" onclick="openWalletTransfer()">⇄ Transferir</button></div>${logs.map(l=>`<div class="it"><div class="t"><b>${escA(l.a||l.src)}</b><span class="mu">${escA(l.n||'')} · ${fmtDate(l.d)}</span></div><b class="${n(l.v)<0?'out':'in'}">${n(l.v)<0?'−':'+'}${brl(Math.abs(n(l.v)))}</b></div>`).join('')||empty('Sem movimentações.')}</div>`}
  function openWalletTransfer(){const opts=walletKeys().map(w=>`<option value="${w.key}">${escA(w.label)} · ${brl(w.balance)}</option>`).join('');M(`<h2>Transferir entre carteiras</h2><label>De</label><select id="v51">${opts}</select><label>Para</label><select id="v52">${opts}</select>${mInput('Valor (R$)','v53','','text','inputmode="decimal"')}<div id="er" class="out"></div><button class="pri" onclick="saveWalletTransfer()">Transferir</button>${btns()}`);$('#v52').selectedIndex=Math.min(1,$('#v52').options.length-1)}window.openWalletTransfer=openWalletTransfer;
  function saveWalletTransfer(){const a=$('#v51').value,b=$('#v52').value,val=pv($('#v53').value);if(a===b||!(val>0))return $('#er').textContent='Escolha origens diferentes e informe o valor.';if(!walletApply(a,-val,'Transferência para '+walletLabel(b)))return;if(!walletApply(b,val,'Transferência de '+walletLabel(a))){walletApply(a,val,'Estorno de transferência');return}audit('Transferência entre carteiras',`${walletLabel(a)} → ${walletLabel(b)} · ${brl(val)}`,'transfer');save();closeM();render()}window.saveWalletTransfer=saveWalletTransfer;
  function openReconcile(){M(`<h2>Conciliação de saldo</h2><label>Carteira</label>${walletSelect('v5wallet')} ${mInput('Saldo real informado (R$)','v51','','text','inputmode="decimal"')}<div id="v5recinfo" class="mu" style="margin-top:8px"></div><button class="pri" onclick="saveReconcile()">Conciliar</button>${btns()}`);$('#v5wallet').onchange=()=>{const w=walletKeys().find(x=>x.key===$('#v5wallet').value);$('#v5recinfo').textContent=w?'Saldo no sistema: '+brl(w.balance):''};$('#v5wallet').dispatchEvent(new Event('change'))}window.openReconcile=openReconcile;
  function saveReconcile(){const key=$('#v5wallet').value,real=pv($('#v51').value),w=walletKeys().find(x=>x.key===key);if(!w||isNaN(real))return toast('Informe o saldo real.');const diff=Math.round((real-w.balance)*100)/100;if(!diff)return toast('Saldo já está conciliado.');if(!walletApply(key,diff,'Ajuste de conciliação'))return;audit('Conciliação de saldo',`${walletLabel(key)} · ajuste ${brl(diff)}`,'reconcile');save();closeM();render()}window.saveReconcile=saveReconcile;

  // Atividades / lixeira / fechamento.
  function renderActivity(){const L=S.v5.audit.slice(0,200);return page('Atividades','Quem fez o quê e quando',L.map(a=>`<div class="card"><div class="row sp"><b>${escA(a.action)}</b><span class="mu">${new Date(a.at).toLocaleString('pt-BR')}</span></div><div style="margin-top:4px">${escA(a.detail)}</div><div class="mu" style="font-size:12px">${escA(a.by||'Usuário')}</div></div>`).join('')||empty('Nenhuma atividade registrada ainda.'))}
  function renderTrash(){const D=S.v5.trash.slice().sort((a,b)=>String(b.deletedAt).localeCompare(String(a.deletedAt)));return page('Lixeira','Itens podem ser restaurados',D.map(t=>`<div class="card"><div class="row sp"><div><b>${escA(t.original?.desc||t.original?.t||t.original?.name||t.original?.brand||t.type)}</b><div class="mu">Excluído por ${escA(t.deletedBy)} · ${new Date(t.deletedAt).toLocaleString('pt-BR')}</div></div><button class="ghost" onclick="restoreTrash('${t.id}')">Restaurar</button></div></div>`).join('')||empty('Lixeira vazia.'),`<button class="ghost v5full" style="margin-bottom:12px" onclick="purgeTrash()">Limpar itens antigos</button>`)}
  function restoreTrash(id){const t=S.v5.trash.find(x=>x.id===id);if(!t)return;const map={tx:'tx',rec:'rec',ev:'ev',acc:'acc',vr:'vr'};const k=map[t.type];if(k&&Array.isArray(S[k])){const o=structuredClone(t.original);stamp(o);S[k].push(o);clearTomb(k,o.id)}v5Tomb('trash',id);S.v5.trash=S.v5.trash.filter(x=>x.id!==id);audit('Item restaurado',t.original?.desc||t.original?.name||t.type,'trash');save();render()}window.restoreTrash=restoreTrash;
  function purgeTrash(){const lim=Date.now()-n(S.v5.settings.trashDays||30)*864e5;for(const t of [...S.v5.trash])if(new Date(t.deletedAt).getTime()<lim){v5Tomb('trash',t.id);S.v5.trash=S.v5.trash.filter(x=>x.id!==t.id)}audit('Lixeira limpa','Itens antigos removidos','trash');save();render();toast('Lixeira limpa.')}window.purgeTrash=purgeTrash;
  function renderCloseMonth(){const months=[...new Set([...S.tx.map(x=>x.date.slice(0,7)),...S.rec.map(x=>x.start.slice(0,7))])].sort().reverse(),closed=new Set(S.v5.closedMonths.map(x=>x.month));return page('Fechamento mensal','Preserve um retrato do mês',`<div class="card">${months.slice(0,18).map(m=>{const l=mEv('all',m),bal=inc(l)-exp(l),is=closed.has(m);return `<div class="it"><div class="t"><b>${mname(m)}</b><span class="mu">Receitas ${brl(inc(l))} · Despesas ${brl(exp(l))}</span></div><b class="${bal<0?'out':'in'}">${brl(bal)}</b><button class="ghost" ${is?'disabled':''} onclick="closeMonthV5('${m}')">${is?'Fechado':'Fechar'}</button></div>`}).join('')}</div>`)}
  function closeMonthV5(m){if(S.v5.closedMonths.some(x=>x.month===m))return;const l=mEv('all',m);v5Add('closedMonths',{month:m,closedAt:isoNow(),income:inc(l),expense:exp(l),balance:inc(l)-exp(l),walletTotal:accTotal(),snapshot:structuredClone(S)});audit('Mês fechado',mname(m),'closemonth');save();render();toast('Mês fechado e preservado.')}window.closeMonthV5=closeMonthV5;

  // Busca universal e filtros.
  function searchAll(q){q=String(q||'').trim().toLowerCase();if(!q)return[];const out=[];const hit=(type,title,sub,obj)=>{const s=(title+' '+sub+' '+JSON.stringify(obj)).toLowerCase();if(s.includes(q))out.push({type,title,sub,obj})};S.tx.forEach(x=>hit('Lançamento',x.desc,`${x.cat} ${x.sup||''} ${brl(x.val)} ${x.date}`,x));S.rec.forEach(x=>hit('Recorrência',x.desc,`${x.cat} ${brl(x.val)}`,x));S.ev.forEach(x=>hit('Compromisso',x.t,`${x.d} ${x.loc||''}`,x));S.v5.suppliers.forEach(x=>hit('Fornecedor',x.name,`${x.pix||''} ${x.taxId||''}`,x));S.v5.shopping.forEach(x=>hit('Compra',x.item,`${x.cat} ${x.qty||''}`,x));S.v5.quotes.forEach(x=>hit('Cotação',x.desc,`${x.supplier||''} ${brl(x.amount)}`,x));return out.slice(0,100)}
  function renderSearch(){const q=window.v5Query||'',R=searchAll(q);return page('Busca universal','Encontre qualquer informação',`<div class="card"><input class="v5search" autofocus placeholder="Ex.: ABC, cimento, outubro, 1.200" value="${escA(q)}" oninput="window.v5Query=this.value;render()"></div>${q?(R.map(r=>`<div class="card"><div class="row sp"><div><b>${escA(r.title)}</b><div class="mu">${escA(r.type)} · ${escA(r.sub)}</div></div>${chip(r.type)}</div></div>`).join('')||empty('Nada encontrado.')):empty('Digite algo para pesquisar.')}`)}

  // Relatórios e exportação CSV.
